def comps(g,sep,count,R,C):
    res=[]
    for r0,r1 in R:
        row=[]
        for c0,c1 in C:
            seen=set();n=0
            for i in range(r0,r1):
                for j in range(c0,c1):
                    if g[i][j]==count and (i,j) not in seen:
                        n+=1;st=[(i,j)]
                        while st:
                            a,b=st.pop()
                            if (a,b) in seen:continue
                            seen.add((a,b))
                            for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                                x,y=a+da,b+db
                                if r0<=x<r1 and c0<=y<c1 and g[x][y]==count and (x,y) not in seen:
                                    st.append((x,y))
            row.append(n)
        res.append(row)
    return res
